window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7aa4638b01948df9"]={"versions": [{"id": "FIG-7aa4638b01948df9", "releases": ["R3.2.3", "R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Spezifikations- und Konfigurationsdiagramm aus der AUTOSAR E2E Library (End-to-End Communication Protection), spezifisch für das Profil E2E Profile 2 (DataIDList-Konzept). Das Diagramm visualisiert die receiver-seitige Zuordnung einer Liste von 16 Data-IDs (<code>DataIDList</code>) zu zyklischen Zählerständen (<code>Counter</code> 0 bis 15) für eine Empfänger-ECU (Receiver-ECU / Receiver B).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine zweidimensionale Matrixstruktur mit folgenden Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Receiver-ECU / Receiver</strong>: Zeilenbezeichner für das empfangende Steuergerät (<code>Receiver B</code>).\n</li><li><strong>message / Counter</strong>: Spaltenindizes von <code>0</code> bis <code>15</code>, die den 4-Bit-Zählerwert (<code>Counter = 0 .. 15</code>) der übertragenen E2E-Nachricht repräsentieren.\n</li><li><strong>DataIDList</strong>: Array von 16 8-Bit-Konfigurationswerten (Data-IDs), die je Zählerstand hinterlegt sind:\n<ul class=\"fig-list\"><li>Counter 0: <code>146</code>\n</li><li>Counter 1: <code>41</code>\n</li><li>Counter 2: <code>187</code>\n</li><li>Counter 3: <code>82</code>\n</li><li>Counter 4: <code>228</code>\n</li><li>Counter 5: <code>123</code>\n</li><li>Counter 6: <code>18</code> (hervorgehoben in Fettdruck)\n</li><li>Counter 7: <code>164</code>\n</li><li>Counter 8: <code>59</code>\n</li><li>Counter 9: <code>205</code>\n</li><li>Counter 10: <code>100</code>\n</li><li>Counter 11: <code>246</code>\n</li><li>Counter 12: <code>141</code>\n</li><li>Counter 13: <code>36</code>\n</li><li>Counter 14: <code>182</code>\n</li><li>Counter 15: <code>77</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Empfang einer geschützten Botschaft mit E2E Profile 2 wertet die Empfänger-ECU (<code>Receiver B</code>) den im Header übertragenen Zählerstand (<code>Counter</code>) aus:</p>\n<ol class=\"fig-list\"><li>Der 4-Bit-Zählerwert (<code>Counter</code> im Bereich 0..15) dient als Index in die konfigurierte <code>DataIDList</code>.\n</li><li>Das Diagramm illustriert exemplarisch den Schritt für <code>Counter = 6</code>: Als zugehörige Daten-ID wird der Wert <code>18</code> selektiert.\n</li><li>Der selektierte Data-ID-Wert fließt zusammen mit den Nutzdaten und dem Zähler in die Prüfsummenberechnung (CRC-Prüfung) zur Verifikation der Datenintegrität und Senderauthentizität ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für E2E Profile 2 (<code>E2E_P02</code>):</p>\n<ul class=\"fig-list\"><li><code>DataIDList</code> muss genau 16 Elemente (<code>uint8</code>) umfassen, passend zum 4-Bit-Counter (Wertebereich 0 bis 15).\n</li><li>Sender und Empfänger müssen identisch konfigurierte Listen besitzen, um einen erfolgreichen CRC-Abgleich zu ermöglichen.\n</li><li>Die Werte müssen eindeutig und pseudozufällig verteilt sein, um Verwechslungen und Datenübertragungsfehler (Aliasing) bei Mehrfachsendern oder Kommunikationsfehlern auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-be83a3ea0f1b5e09", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Spezifikations- und Konfigurationsdiagramm aus der AUTOSAR E2E Library (End-to-End Communication Protection), spezifisch für das Profil E2E Profile 2 (DataIDList-Konzept). Das Diagramm visualisiert die receiver-seitige Zuordnung einer Liste von 16 Data-IDs (<code>DataIDList</code>) zu zyklischen Zählerständen (<code>Counter</code> 0 bis 15) für eine Empfänger-ECU (Receiver-ECU / Receiver B).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine zweidimensionale Matrixstruktur mit folgenden Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Receiver-ECU / Receiver</strong>: Zeilenbezeichner für das empfangende Steuergerät (<code>Receiver B</code>).\n</li><li><strong>message / Counter</strong>: Spaltenindizes von <code>0</code> bis <code>15</code>, die den 4-Bit-Zählerwert (<code>Counter = 0 .. 15</code>) der übertragenen E2E-Nachricht repräsentieren.\n</li><li><strong>DataIDList</strong>: Array von 16 8-Bit-Konfigurationswerten (Data-IDs), die je Zählerstand hinterlegt sind:\n<ul class=\"fig-list\"><li>Counter 0: <code>146</code>\n</li><li>Counter 1: <code>41</code>\n</li><li>Counter 2: <code>187</code>\n</li><li>Counter 3: <code>82</code>\n</li><li>Counter 4: <code>228</code>\n</li><li>Counter 5: <code>123</code>\n</li><li>Counter 6: <code>18</code> (hervorgehoben in Fettdruck)\n</li><li>Counter 7: <code>164</code>\n</li><li>Counter 8: <code>59</code>\n</li><li>Counter 9: <code>205</code>\n</li><li>Counter 10: <code>100</code>\n</li><li>Counter 11: <code>246</code>\n</li><li>Counter 12: <code>141</code>\n</li><li>Counter 13: <code>36</code>\n</li><li>Counter 14: <code>182</code>\n</li><li>Counter 15: <code>77</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Empfang einer geschützten Botschaft mit E2E Profile 2 wertet die Empfänger-ECU (<code>Receiver B</code>) den im Header übertragenen Zählerstand (<code>Counter</code>) aus:</p>\n<ol class=\"fig-list\"><li>Der 4-Bit-Zählerwert (<code>Counter</code> im Bereich 0..15) dient als Index in die konfigurierte <code>DataIDList</code>.\n</li><li>Das Diagramm illustriert exemplarisch den Schritt für <code>Counter = 6</code>: Als zugehörige Daten-ID wird der Wert <code>18</code> selektiert.\n</li><li>Der selektierte Data-ID-Wert fließt zusammen mit den Nutzdaten und dem Zähler in die Prüfsummenberechnung (CRC-Prüfung) zur Verifikation der Datenintegrität und Senderauthentizität ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für E2E Profile 2 (<code>E2E_P02</code>):</p>\n<ul class=\"fig-list\"><li><code>DataIDList</code> muss genau 16 Elemente (<code>uint8</code>) umfassen, passend zum 4-Bit-Counter (Wertebereich 0 bis 15).\n</li><li>Sender und Empfänger müssen identisch konfigurierte Listen besitzen, um einen erfolgreichen CRC-Abgleich zu ermöglichen.\n</li><li>Die Werte müssen eindeutig und pseudozufällig verteilt sein, um Verwechslungen und Datenübertragungsfehler (Aliasing) bei Mehrfachsendern oder Kommunikationsfehlern auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3d63e9ced2f09ec3", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Tabellarisches Spezifikations- und Konfigurationsdiagramm aus der AUTOSAR E2E Library (End-to-End Communication Protection), spezifisch für das Profil E2E Profile 2 (DataIDList-Konzept). Das Diagramm visualisiert die receiver-seitige Zuordnung einer Liste von 16 Data-IDs (<code>DataIDList</code>) zu zyklischen Zählerständen (<code>Counter</code> 0 bis 15) für eine Empfänger-ECU (Receiver-ECU / Receiver B).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine zweidimensionale Matrixstruktur mit folgenden Entitäten:</p>\n<ul class=\"fig-list\"><li><strong>Receiver-ECU / Receiver</strong>: Zeilenbezeichner für das empfangende Steuergerät (<code>Receiver B</code>).\n</li><li><strong>message / Counter</strong>: Spaltenindizes von <code>0</code> bis <code>15</code>, die den 4-Bit-Zählerwert (<code>Counter = 0 .. 15</code>) der übertragenen E2E-Nachricht repräsentieren.\n</li><li><strong>DataIDList</strong>: Array von 16 8-Bit-Konfigurationswerten (Data-IDs), die je Zählerstand hinterlegt sind:\n<ul class=\"fig-list\"><li>Counter 0: <code>146</code>\n</li><li>Counter 1: <code>41</code>\n</li><li>Counter 2: <code>187</code>\n</li><li>Counter 3: <code>82</code>\n</li><li>Counter 4: <code>228</code>\n</li><li>Counter 5: <code>123</code>\n</li><li>Counter 6: <code>18</code> (hervorgehoben in Fettdruck)\n</li><li>Counter 7: <code>164</code>\n</li><li>Counter 8: <code>59</code>\n</li><li>Counter 9: <code>205</code>\n</li><li>Counter 10: <code>100</code>\n</li><li>Counter 11: <code>246</code>\n</li><li>Counter 12: <code>141</code>\n</li><li>Counter 13: <code>36</code>\n</li><li>Counter 14: <code>182</code>\n</li><li>Counter 15: <code>77</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Bei Empfang einer geschützten Botschaft mit E2E Profile 2 wertet die Empfänger-ECU (<code>Receiver B</code>) den im Header übertragenen Zählerstand (<code>Counter</code>) aus:</p>\n<ol class=\"fig-list\"><li>Der 4-Bit-Zählerwert (<code>Counter</code> im Bereich 0..15) dient als Index in die konfigurierte <code>DataIDList</code>.\n</li><li>Das Diagramm illustriert exemplarisch den Schritt für <code>Counter = 6</code>: Als zugehörige Daten-ID wird der Wert <code>18</code> selektiert.\n</li><li>Der selektierte Data-ID-Wert fließt zusammen mit den Nutzdaten und dem Zähler in die Prüfsummenberechnung (CRC-Prüfung) zur Verifikation der Datenintegrität und Senderauthentizität ein.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Konfigurationsvorgabe für E2E Profile 2 (<code>E2E_P02</code>):</p>\n<ul class=\"fig-list\"><li><code>DataIDList</code> muss genau 16 Elemente (<code>uint8</code>) umfassen, passend zum 4-Bit-Counter (Wertebereich 0 bis 15).\n</li><li>Sender und Empfänger müssen identisch konfigurierte Listen besitzen, um einen erfolgreichen CRC-Abgleich zu ermöglichen.\n</li><li>Die Werte müssen eindeutig und pseudozufällig verteilt sein, um Verwechslungen und Datenübertragungsfehler (Aliasing) bei Mehrfachsendern oder Kommunikationsfehlern auszuschließen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-7aa4638b01948df9", "to": "FIG-be83a3ea0f1b5e09", "fr": "R3.2.3", "tr": "R4.0.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-be83a3ea0f1b5e09", "to": "FIG-7aa4638b01948df9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7aa4638b01948df9", "to": "FIG-3d63e9ced2f09ec3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
